import React, { useState, useEffect } from 'react';
import { collection, query, where, onSnapshot, deleteDoc, doc } from 'firebase/firestore';
import { db, auth } from '../../firebase';
import { onAuthStateChanged } from 'firebase/auth';

const MyAds = () => {
  const [user, setUser] = useState(null);
  const [ads, setAds] = useState([]);

  useEffect(() => {
    const unsubscribe = onAuthStateChanged(auth, (currentUser) => {
      setUser(currentUser);
    });
    return () => unsubscribe();
  }, []);

  useEffect(() => {
    if (user) {
      const q = query(collection(db, 'posts'), where('userId', '==', user.uid));

      const unsubscribe = onSnapshot(q, (querySnapshot) => {
        const adsArray = [];
        querySnapshot.forEach((doc) => {
          adsArray.push({ id: doc.id, ...doc.data() });
        });
        setAds(adsArray);
      });

      return () => unsubscribe();
    }
  }, [user]);

  const handleDelete = async (id) => {
    try {
      await deleteDoc(doc(db, 'posts', id));
      setAds(ads.filter((ad) => ad.id !== id));
    } catch (error) {
      console.error('Error deleting ad:', error);
    }
  };

  return (
    <div className="container mx-auto px-4 py-8">
      <h1 className="text-2xl font-semibold mb-4">My Ads</h1>
      <div className="bg-white p-4 rounded-lg shadow-md">
        {ads.length > 0 ? (
          ads.map((ad) => (
            <div key={ad.id} className="mb-2 p-2 rounded-lg bg-gray-100 flex justify-between items-center">
              <div>
            <img src={ad.imageUrl} alt={ad.title} className="w-16 h-16 object-cover rounded-lg mr-4" />

                <p className="text-sm font-bold">{ad.title}</p>
                <p className="text-sm text-gray-600">{ad.description}</p>
              </div>
              <button
                onClick={() => handleDelete(ad.id)}
                className="bg-red-500 text-white px-4 py-2 rounded-md hover:bg-red-700"
              >
                Delete
              </button>
            </div>
          ))
        ) : (
          <p className="text-gray-600">No ads available</p>
        )}
      </div>
    </div>
  );
};

export default MyAds;
